import { addUsage, callVerifier, emptyUsage, predictScoringChannel, requestAttempts, type ScoringMode, type UsageStats, type VerifierClientConfig, type VerifierImage } from './caller.ts'
import { ScoreCache, SingleFlight, stableHash, type CachedPairScore } from './cache.ts'
import type { DecisionTrace } from './decisions.ts'
import {
  DEFAULT_CRITERIA, DEFAULT_GROUND_TRUTH_NOTE, accumulatePairs, buildPairwisePrompt, buildProgressPrompt,
  dedupeCriterionId, extractProgressScore, extractScore, pivotRoundPairs, rankScores, ringCycle, slugCriterionId,
  topPivots, type Criterion,
} from './core.ts'

export interface CompareOptions { problem: string; candidateA: string; candidateB: string; criteria?: readonly Criterion[]; groundTruthNote?: string; repeats?: number; images?: readonly VerifierImage[]; trace?: DecisionTrace; /** Prefix for this comparison's decision-snapshot labels; one invocation that judges twice on the same criteria needs them distinguishable. */ traceLabelPrefix?: string }
export interface CriterionResult { id: string; name: string; scoreA: number; scoreB: number }
export interface RunStats extends UsageStats {
  cacheHits: number
  cacheMisses: number
  estimatedCostUsd: number
  topLogprobScores: number
  explicitTagScores: number
  /**
   * At least one request failed before returning usage. The tokens it may have spent are
   * UNKNOWN, not zero: a failed call must not make the invocation look free.
   */
  usageIncomplete?: boolean
  /** Calls that were attempted on the direct logprob transport and downgraded to explicit tags. */
  channelFallbacks?: number
}

export interface JudgeScore {
  provider: string
  model: string
  label: string
  ok: boolean
  calls: number
  error?: string
  scoreA?: number
  scoreB?: number
  winner?: 'A' | 'B' | 'tie'
  scores?: number[]
  ranking?: number[]
}

export interface CompareResult {
  scoreA: number
  scoreB: number
  winner: 'A' | 'B' | 'tie'
  criteria: CriterionResult[]
  calls: number
  stats: RunStats
  judges: JudgeScore[]
  agreement: number
  /** Set when both sides were byte-identical: no model call was made and both sides score 0.5. */
  identical?: true
}

export interface SelectOptions { problem: string; candidates: readonly string[]; criteria?: readonly Criterion[]; groundTruthNote?: string; repeats?: number; pivots?: number; seed?: number; images?: readonly VerifierImage[]; trace?: DecisionTrace }

export interface SelectResult {
  index: number
  best: string
  scores: number[]
  ranking: number[]
  pivots: number[]
  comparisons: number
  calls: number
  stats: RunStats
  judges: JudgeScore[]
  /** Set when every candidate was byte-identical: no pair was judged and every score is 0.5. */
  identical?: true
}

function average(values: readonly number[]): number { return values.reduce((sum, value) => sum + value, 0) / (values.length || 1) }

function median(values: readonly number[]): number {
  if (values.length === 0) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 !== 0 ? sorted[mid]! : (sorted[mid - 1]! + sorted[mid]!) / 2
}

function blankStats(): RunStats { return { ...emptyUsage(), cacheHits: 0, cacheMisses: 0, estimatedCostUsd: 0, topLogprobScores: 0, explicitTagScores: 0 } }
/** Candidate indices best-first by score, ties broken by index. */
function rankByScore(scores: readonly number[]): number[] { return Array.from({ length: scores.length }, (_, index) => index).sort((a, b) => (scores[b] ?? 0) - (scores[a] ?? 0) || a - b) }
function unorderedPair(a: number, b: number): string { return a < b ? a + ',' + b : b + ',' + a }

/**
 * Deterministic A/B slot for one pivot-round pair, balanced by construction.
 *
 * The round used to emit `[candidate, pivot]` for every edge, so the ring leaders sat
 * in trajectory B in all of their extra matches: with a judge that merely prefers slot A
 * the pivots averaged 0.36 against 0.60 for everyone else and sank in the final ranking.
 * Alternating on the sum of the two RANKS — not the raw indices: the pivot set is
 * selected by score, so its indices can share a parity and a parity rule would then
 * handicap half the field — gives every pivot and every candidate both slots within one
 * edge of each other, without a second model call.
 *
 * Deliberately NOT in core.ts: `pivotRoundPairs` is compared against the upstream Python
 * reference in `parity.test.ts`, so the orientation stays an orchestration-side decision.
 * @param pair - one unordered pair from the pivot round.
 * @param pivotRanks - pivot index → its rank among the pivots.
 * @param nonPivotRanks - candidate index → its rank among the non-pivots.
 * @returns The pair in the order it should be presented.
 */
export function orientRoundPairs(pairs: readonly (readonly [number, number])[]): Array<[number, number]> {
  const balance = new Map<number, number>()
  return pairs.map(([a, b]) => {
    const first = balance.get(a) ?? 0
    const second = balance.get(b) ?? 0
    // Slot A goes to whichever endpoint has held it less often; an equal count keeps the
    // incoming order, so the result is deterministic for a given pair sequence.
    const [x, y] = second < first ? [b, a] : [a, b]
    balance.set(x, (balance.get(x) ?? 0) + 1)
    balance.set(y, (balance.get(y) ?? 0) - 1)
    return [x, y] as [number, number]
  })
}

/**
 * Arbitrary but fixed A/B slot for the single pair of a two-candidate select.
 *
 * There is only one match, so nothing can cancel a preference; the mix at least stops
 * candidate 0 from always sitting in slot A. Real comparisons go through `compare`,
 * where `routedRepeats` runs an even number of rounds instead.
 * @param a - first candidate index of the pair.
 * @param b - second candidate index of the pair.
 * @returns The pair in the order it should be presented.
 */
function orientPair(a: number, b: number): [number, number] {
  const lo = Math.min(a, b)
  const hi = Math.max(a, b)
  let mixed = Math.imul(lo + 1, 0x9e3779b1) ^ Math.imul(hi + 1, 0x85ebca77)
  mixed = Math.imul(mixed ^ (mixed >>> 15), 0x2545f491)
  return ((mixed ^ (mixed >>> 13)) & 1) === 0 ? [a, b] : [b, a]
}

function judgeLabel(client: VerifierClientConfig): string {
  return client.label?.trim() || client.provider + '/' + client.model
}

export class VerifierEngine {
  readonly client: VerifierClientConfig
  readonly clients: readonly VerifierClientConfig[]
  readonly maxConcurrency: number
  readonly cache: ScoreCache | undefined
  readonly inputPrice: number
  readonly outputPrice: number
  private readonly flights: SingleFlight<{ value: CachedPairScore; hit: boolean }>

  constructor(
    client: VerifierClientConfig | readonly VerifierClientConfig[],
    maxConcurrency = 8,
    cache?: ScoreCache,
    prices: { input: number; output: number } = { input: 0, output: 0 },
    flights: SingleFlight<{ value: CachedPairScore; hit: boolean }> = new SingleFlight(),
  ) {
    const list = Array.isArray(client) ? client : [client]
    if (!list.length) throw new Error('llm-verifier: at least one verifier client is required')
    this.clients = list
    this.client = list[0]!
    this.maxConcurrency = maxConcurrency
    this.cache = cache
    this.inputPrice = prices.input
    this.outputPrice = prices.output
    this.flights = flights
  }

  private finishStats(stats: RunStats): RunStats {
    stats.estimatedCostUsd = ((stats.inputTokens + stats.cachedInputTokens) * this.inputPrice + stats.outputTokens * this.outputPrice) / 1_000_000
    return stats
  }

  private async scoreOne(client: VerifierClientConfig, options: CompareOptions, candidateA: string, candidateB: string, criterion: Criterion, repeat: number, signal?: AbortSignal): Promise<{ scores: readonly [number, number]; usage: UsageStats; scoringMode: 'top-logprobs' | 'explicit-tag'; hit: boolean; channelFallback: boolean }> {
    const ground = options.groundTruthNote ?? DEFAULT_GROUND_TRUTH_NOTE
    const prompt = buildPairwisePrompt(options.problem, candidateA, candidateB, criterion, ground)
    const imageKey = options.images?.map(image => stableHash([image.mediaType, Buffer.from(image.data).toString('base64')]))
    // Cache identity pins the scoring channel, but the channel is only predictable
    // before the call when the capability cache already knows the answer. Lookups use
    // the predicted channel while entries are always stored under the ACTUAL
    // completion mode, so a first-call downgrade lands under explicit-tag keys and is
    // found by later explicit-tag calls instead of being misread as a top-logprobs
    // expectation. The channel stays OUT of the in-flight dedup key below.
    const identity = { version: 6, provider: client.provider, model: client.model, effort: client.reasoningEffort, maxTokens: client.maxTokens, temperature: client.temperature, repeat, promptHash: stableHash(prompt), imageKey }
    const keyForMode = (scoringMode: ScoringMode) => stableHash({ ...identity, scoringMode })
    // Captured out of band: a fallback describes the REQUEST, not the score, so it must not
    // enter the cached value (a cache hit later must not claim a downgrade that never happened).
    let fellBack = false
    const create = async () => {
      const completion = await callVerifier(client, prompt, signal, options.images)
      const scoreA = extractScore(completion, '<score_A>')
      const scoreB = extractScore(completion, '<score_B>')
      fellBack = completion.channelFallback === true
      // Traced here, not in scoreOne(): a cache hit or a merged in-flight call makes no
      // model call, and a snapshot that showed one anyway would be a fabrication.
      options.trace?.({ label: (options.traceLabelPrefix ?? '') + criterion.name + ' repeat ' + (repeat + 1), channel: completion.scoringMode, prompt, output: completion.text, score: scoreA })
      return { scoreA, scoreB, usage: completion.usage, scoringMode: completion.scoringMode, createdAt: Date.now() }
    }
    const cache = this.cache
    if (cache === undefined) { const value = await create(); return { scores: [value.scoreA, value.scoreB], usage: value.usage, scoringMode: value.scoringMode, hit: false, channelFallback: fellBack } }
    // Registration happens in the synchronous segment before any await, so a request
    // that arrives while the first one is still resolving its channel prediction
    // still merges instead of duplicating the model call. The flight table is shared
    // per topic, so concurrent tool calls through separate engine instances merge too.
    const dedupeKey = stableHash(identity)
    const outcome = await this.flights.run(dedupeKey, async () => cache.getOrCreate(keyForMode(await predictScoringChannel(client)), create, value => keyForMode(value.scoringMode)))
    const landed = outcome.value
    const reused = outcome.joined || landed.hit
    return { scores: [landed.value.scoreA, landed.value.scoreB], usage: reused ? emptyUsage() : landed.value.usage, scoringMode: landed.value.scoringMode, hit: reused, channelFallback: reused ? false : fellBack }
  }

  private async mapLimited<T, R>(items: readonly T[], worker: (item: T) => Promise<R>): Promise<R[]> {
    const results = new Array<R>(items.length); let cursor = 0
    const runners = Array.from({ length: Math.min(this.maxConcurrency, items.length) }, async () => { while (cursor < items.length) { const index = cursor++; results[index] = await worker(items[index]!) } })
    await Promise.all(runners); return results
  }

  /**
   * Verdict for a comparison whose two sides are byte-identical.
   *
   * Deliberately uninformative: no model call is made, both sides score 0.5 and the winner is
   * a tie. Judging identical text would ask the model to break a tie it cannot break, and any
   * confident score would let the acceptance gate pass a session indistinguishable from the
   * empty-work baseline. Callers that need "these are the same" read {@link CompareResult.identical}.
   * @param criteria - the criteria the comparison would have scored.
   * @returns A tie carrying 0.5 per criterion, zero calls and one agreeing judge per client.
   */
  private informationalTie(criteria: readonly Criterion[]): CompareResult {
    const judges: JudgeScore[] = this.clients.map(client => ({ provider: client.provider, model: client.model, label: judgeLabel(client), ok: true, calls: 0, scoreA: 0.5, scoreB: 0.5, winner: 'tie' as const }))
    return {
      scoreA: 0.5,
      scoreB: 0.5,
      winner: 'tie',
      criteria: criteria.map(criterion => ({ id: criterion.id, name: criterion.name, scoreA: 0.5, scoreB: 0.5 })),
      calls: 0,
      stats: this.finishStats(blankStats()),
      judges,
      agreement: 1,
      identical: true,
    }
  }

  async compare(options: CompareOptions, signal?: AbortSignal): Promise<CompareResult> {
    const criteria = options.criteria?.length ? options.criteria : DEFAULT_CRITERIA
    if (options.candidateA === options.candidateB) return this.informationalTie(criteria)
    const repeats = options.repeats ?? 2
    const jobs = criteria.flatMap(criterion => Array.from({ length: repeats }, (_, repeat) => ({ criterion, repeat })))
    // Prefix warm-up: one job per DISTINCT prompt prefix runs first, then the rest fan out.
    // Only the A/B slot order changes the prompt prefix (the criterion sits at the tail, see
    // core.buildPairwisePrompt) and odd repeats swap the slots, so each orientation needs its own
    // warm call: warming a single job left every swapped-slot call cold, which is where half the
    // input tokens of a session acceptance went. The warm jobs are calls that had to happen anyway.
    const warm: typeof jobs = []; const rest: typeof jobs = []
    const warmedOrientations = new Set<number>()
    for (const job of jobs) {
      const orientation = job.repeat % 2
      if (warmedOrientations.has(orientation)) rest.push(job)
      else { warmedOrientations.add(orientation); warm.push(job) }
    }
    const run = async (batch: typeof jobs) => this.mapLimited(batch, async ({ criterion, repeat }) => {
      const swapped = repeat % 2 === 1
      const candA = swapped ? options.candidateB : options.candidateA
      const candB = swapped ? options.candidateA : options.candidateB
      const judgeResults = await Promise.all(
        this.clients.map(async (client, k) => {
          try {
            const res = await this.scoreOne(client, options, candA, candB, criterion, repeat, signal)
            return {
              k,
              ok: true as const,
              scoreA: swapped ? res.scores[1] : res.scores[0],
              scoreB: swapped ? res.scores[0] : res.scores[1],
              usage: res.usage,
              scoringMode: res.scoringMode,
              hit: res.hit,
              channelFallback: res.channelFallback,
            }
          } catch (error) {
            return {
              k,
              ok: false as const,
              error,
            }
          }
        })
      )
      const successful = judgeResults.filter((r): r is Extract<typeof r, { ok: true }> => r.ok)
      if (successful.length === 0) {
        const firstFail = judgeResults.find(r => !r.ok)! as Extract<typeof judgeResults[number], { ok: false }>
        throw firstFail.error
      }
      const leafScoreA = median(successful.map(r => r.scoreA))
      const leafScoreB = median(successful.map(r => r.scoreB))
      return { criterion, repeat, leafScoreA, leafScoreB, judgeResults }
    })

    const jobOutcomes = [...await run(warm), ...await run(rest)]
    const stats = blankStats()
    const judgeCalls = new Array<number>(this.clients.length).fill(0)
    const judgeOk = new Array<boolean>(this.clients.length).fill(true)
    const judgeErrors = new Array<string | undefined>(this.clients.length).fill(undefined)
    const judgeJobScores: Array<Array<{ criterionId: string; scoreA: number; scoreB: number }>> = Array.from(
      { length: this.clients.length },
      () => []
    )

    for (const outcome of jobOutcomes) {
      for (const r of outcome.judgeResults) {
        if (r.ok) {
          judgeCalls[r.k] += r.usage.calls
          judgeJobScores[r.k]!.push({ criterionId: outcome.criterion.id, scoreA: r.scoreA, scoreB: r.scoreB })
          addUsage(stats, r.usage)
          if (r.hit) stats.cacheHits++
          else stats.cacheMisses++
          if (r.scoringMode === 'top-logprobs') stats.topLogprobScores++
          else stats.explicitTagScores++
          if (r.channelFallback) stats.channelFallbacks = (stats.channelFallbacks ?? 0) + 1
        } else {
          judgeOk[r.k] = false
          // The failed request really happened even though its usage is unknown; the attempt
          // count is kind-independent, so it is kept and the row is marked incomplete rather
          // than reported as a confident zero-cost call.
          stats.attempts += requestAttempts(r.error)
          stats.usageIncomplete = true
          if (judgeErrors[r.k] === undefined) {
            judgeErrors[r.k] = r.error instanceof Error ? r.error.message : String(r.error)
          }
        }
      }
    }

    const byCriterion = criteria.map(criterion => {
      const rows = jobOutcomes.filter(row => row.criterion.id === criterion.id)
      return {
        id: criterion.id,
        name: criterion.name,
        scoreA: average(rows.map(row => row.leafScoreA)),
        scoreB: average(rows.map(row => row.leafScoreB)),
      }
    })
    const scoreA = average(byCriterion.map(value => value.scoreA))
    const scoreB = average(byCriterion.map(value => value.scoreB))
    const winner: 'A' | 'B' | 'tie' = Math.abs(scoreA - scoreB) < 1e-12 ? 'tie' : scoreA > scoreB ? 'A' : 'B'

    const judges: JudgeScore[] = this.clients.map((client, k) => {
      const isOk = judgeOk[k]!
      if (!isOk) {
        return {
          provider: client.provider,
          model: client.model,
          label: judgeLabel(client),
          ok: false,
          calls: judgeCalls[k]!,
          ...(judgeErrors[k] !== undefined ? { error: judgeErrors[k] } : {}),
        }
      }
      const jByCriterion = criteria.map(criterion => {
        const rows = judgeJobScores[k]!.filter(row => row.criterionId === criterion.id)
        return {
          scoreA: average(rows.map(row => row.scoreA)),
          scoreB: average(rows.map(row => row.scoreB)),
        }
      })
      const jScoreA = average(jByCriterion.map(c => c.scoreA))
      const jScoreB = average(jByCriterion.map(c => c.scoreB))
      const jWinner: 'A' | 'B' | 'tie' = Math.abs(jScoreA - jScoreB) < 1e-12 ? 'tie' : jScoreA > jScoreB ? 'A' : 'B'
      return {
        provider: client.provider,
        model: client.model,
        label: judgeLabel(client),
        ok: true,
        calls: judgeCalls[k]!,
        scoreA: jScoreA,
        scoreB: jScoreB,
        winner: jWinner,
      }
    })

    const scoringJudges = judges.filter(j => j.ok && j.winner !== undefined)
    const agreement = scoringJudges.length === 0
      ? 0
      : scoringJudges.length === 1
        ? 1
        : scoringJudges.filter(j => j.winner === winner).length / scoringJudges.length

    return {
      scoreA,
      scoreB,
      winner,
      criteria: byCriterion,
      calls: stats.calls,
      stats: this.finishStats(stats),
      judges,
      agreement,
    }
  }

  private async scorePairs(options: SelectOptions, pairs: readonly [number, number][], signal?: AbortSignal): Promise<{
    rewards: Map<string, readonly [number, number]>
    judgeRewards: Array<Map<string, readonly [number, number]>>
    judgeOk: boolean[]
    judgeErrors: Array<string | undefined>
    judgeCalls: number[]
    stats: RunStats
  }> {
    const unique = [...new Map(pairs.map(pair => [pair[0] + ',' + pair[1], pair])).values()]
    const values = await this.mapLimited(unique, async ([a, b]) => ({
      a,
      b,
      result: await this.compare({
        problem: options.problem,
        candidateA: options.candidates[a]!,
        candidateB: options.candidates[b]!,
        criteria: options.criteria,
        groundTruthNote: options.groundTruthNote,
        repeats: options.repeats,
        images: options.images,
        trace: options.trace,
      }, signal),
    }))
    const rewards = new Map<string, readonly [number, number]>()
    const judgeRewards: Array<Map<string, readonly [number, number]>> = Array.from({ length: this.clients.length }, () => new Map())
    const judgeOk = new Array<boolean>(this.clients.length).fill(true)
    const judgeErrors = new Array<string | undefined>(this.clients.length).fill(undefined)
    const judgeCalls = new Array<number>(this.clients.length).fill(0)
    const stats = blankStats()

    for (const value of values) {
      const pairKey = value.a + ',' + value.b
      rewards.set(pairKey, [value.result.scoreA, value.result.scoreB])
      addUsage(stats, value.result.stats)
      stats.cacheHits += value.result.stats.cacheHits
      stats.cacheMisses += value.result.stats.cacheMisses
      stats.topLogprobScores += value.result.stats.topLogprobScores
      stats.explicitTagScores += value.result.stats.explicitTagScores
      if (value.result.stats.usageIncomplete) stats.usageIncomplete = true
      if (value.result.stats.channelFallbacks) stats.channelFallbacks = (stats.channelFallbacks ?? 0) + value.result.stats.channelFallbacks

      for (let k = 0; k < this.clients.length; k++) {
        const js = value.result.judges[k]!
        judgeCalls[k] += js.calls
        if (js.ok && js.scoreA !== undefined && js.scoreB !== undefined) {
          judgeRewards[k]!.set(pairKey, [js.scoreA, js.scoreB])
        } else {
          judgeOk[k] = false
          if (judgeErrors[k] === undefined && js.error) {
            judgeErrors[k] = js.error
          }
        }
      }
    }
    return { rewards, judgeRewards, judgeOk, judgeErrors, judgeCalls, stats: this.finishStats(stats) }
  }

  async track(problem: string, steps: readonly string[], checkpoints: readonly number[], repeats = 2, signal?: AbortSignal, images?: readonly VerifierImage[], trace?: DecisionTrace): Promise<{ scores: number[]; perRepeat: number[][]; calls: number; stats: RunStats; judges: JudgeScore[] }> {
    if (!steps.length || !checkpoints.length) throw new Error('llm-verifier: steps and checkpoints must not be empty')
    for (const checkpoint of checkpoints) if (!Number.isSafeInteger(checkpoint) || checkpoint < 1 || checkpoint > steps.length) throw new Error('llm-verifier: each checkpoint must be an integer between 1 and steps.length')
    const prompt = buildProgressPrompt(problem, steps, checkpoints)
    const stats = blankStats()
    const judgeCalls = new Array<number>(this.clients.length).fill(0)
    const judgeOk = new Array<boolean>(this.clients.length).fill(true)
    const judgeErrors = new Array<string | undefined>(this.clients.length).fill(undefined)
    const judgePerRepeatScores: Array<number[][]> = Array.from({ length: this.clients.length }, () => [])

    const repeatIndices = Array.from({ length: repeats }, (_, index) => index)
    const runRepeat = async (repeatIndex: number) => {
      const judgeResults = await Promise.all(
        this.clients.map(async (client, k) => {
          try {
            const completion = await callVerifier(client, prompt, signal, images)
            const scores = checkpoints.map((_, index) => extractProgressScore(completion, '<c' + (index + 1) + '>'))
            // One snapshot per repeat for the primary judge only: extra judges would
            // multiply the record past its budget, and the primary is what the verdict
            // reports.
            if (k === 0) trace?.({ label: 'progress repeat ' + (repeatIndex + 1) + '/' + repeats + (this.clients.length > 1 ? ' judge 1/' + this.clients.length : ''), channel: completion.scoringMode, prompt, output: completion.text, score: scores[scores.length - 1] })
            return {
              k,
              ok: true as const,
              completion,
              scores,
            }
          } catch (error) {
            return {
              k,
              ok: false as const,
              error,
            }
          }
        })
      )

      const successful = judgeResults.filter((r): r is Extract<typeof r, { ok: true }> => r.ok)
      if (successful.length === 0) {
        const firstFail = judgeResults.find(r => !r.ok)! as Extract<typeof judgeResults[number], { ok: false }>
        throw firstFail.error
      }

      for (const r of judgeResults) {
        if (r.ok) {
          judgeCalls[r.k] += r.completion.usage.calls
          judgePerRepeatScores[r.k]!.push(r.scores)
          addUsage(stats, r.completion.usage)
          if (r.completion.scoringMode === 'top-logprobs') stats.topLogprobScores++
          else stats.explicitTagScores++
          if (r.completion.channelFallback) stats.channelFallbacks = (stats.channelFallbacks ?? 0) + 1
        } else {
          judgeOk[r.k] = false
          stats.attempts += requestAttempts(r.error)
          stats.usageIncomplete = true
          if (judgeErrors[r.k] === undefined) {
            judgeErrors[r.k] = r.error instanceof Error ? r.error.message : String(r.error)
          }
        }
      }

      return checkpoints.map((_, cIndex) => median(successful.map(r => r.scores[cIndex]!)))
    }
    // Every repeat sends the SAME prompt, so the first repeat warms the provider prefix cache for
    // the others; fanning all repeats out at once left every call cold. The repeat count is
    // unchanged — only the order, and therefore the cache hits, change.
    const runs: number[][] = []
    if (repeatIndices.length > 0) runs.push(...await this.mapLimited(repeatIndices.slice(0, 1), runRepeat))
    runs.push(...await this.mapLimited(repeatIndices.slice(1), runRepeat))

    const scores = checkpoints.map((_, index) => average(runs.map(run => run[index]!)))
    const judges: JudgeScore[] = this.clients.map((client, k) => {
      const isOk = judgeOk[k]!
      if (!isOk) {
        return {
          provider: client.provider,
          model: client.model,
          label: judgeLabel(client),
          ok: false,
          calls: judgeCalls[k]!,
          ...(judgeErrors[k] !== undefined ? { error: judgeErrors[k] } : {}),
        }
      }
      const jRuns = judgePerRepeatScores[k]!
      const jScores = checkpoints.map((_, index) => average(jRuns.map(run => run[index]!)))
      return {
        provider: client.provider,
        model: client.model,
        label: judgeLabel(client),
        ok: true,
        calls: judgeCalls[k]!,
        scores: jScores,
      }
    })

    return { scores, perRepeat: runs, calls: stats.calls, stats: this.finishStats(stats), judges }
  }

  /**
   * Verdict for a candidate list whose entries are all byte-identical.
   *
   * Ranking identical text is a coin flip, so the result is deliberately uninformative
   * (0.5 everywhere) rather than a confident 1.0. No model call is made. This is the
   * cost-saving half of upstream's majority-vote shortcut without its semantics: we never
   * declare an unjudged candidate the winner, we only decline to spend calls on a tie.
   * @param candidates - the identical candidates (length >= 2).
   * @returns A ranking with every score at 0.5 and zero calls.
   */
  private identicalCandidates(candidates: readonly string[]): SelectResult {
    const scores = candidates.map(() => 0.5)
    const ranking = candidates.map((_, index) => index)
    return {
      index: 0,
      best: candidates[0]!,
      scores,
      ranking,
      pivots: [],
      comparisons: 0,
      calls: 0,
      stats: blankStats(),
      judges: this.clients.map(client => ({ provider: client.provider, model: client.model, label: judgeLabel(client), ok: true, calls: 0, scores: [...scores], ranking: [...ranking] })),
      identical: true,
    }
  }

  /**
   * Judge only the DISTINCT candidates, then expand the verdict back onto the caller's list.
   *
   * Duplicated candidates are the common case when an agent pastes several drafts of the same
   * artifact: every pair that touches a duplicate is a comparison that cannot change the
   * ranking but still costs model calls. The tournament runs on the distinct list and every
   * duplicate inherits its representative's score, so no index, score or ranking entry shifts.
   * @param options - the original select options, duplicates included.
   * @param signal - caller's abort signal.
   * @returns The tournament verdict mapped back onto the original candidate list.
   */
  private async selectUnique(options: SelectOptions, signal?: AbortSignal): Promise<SelectResult> {
    const unique: string[] = []
    const representative: number[] = []
    const seen = new Map<string, number>()
    for (const candidate of options.candidates) {
      let index = seen.get(candidate)
      if (index === undefined) { index = unique.length; unique.push(candidate); seen.set(candidate, index) }
      representative.push(index)
    }
    const result = await this.select({ ...options, candidates: unique }, signal)
    const expand = (values: readonly number[]): number[] => representative.map(index => values[index] ?? 0)
    const scores = expand(result.scores)
    const judges = result.judges.map(judge => {
      if (!judge.ok || judge.scores === undefined) return judge
      const judgeScores = expand(judge.scores)
      return { ...judge, scores: judgeScores, ...(judge.ranking === undefined ? {} : { ranking: rankByScore(judgeScores) }) }
    })
    return {
      index: options.candidates.indexOf(result.best),
      best: result.best,
      scores,
      ranking: rankByScore(scores),
      pivots: result.pivots,
      comparisons: result.comparisons,
      calls: result.calls,
      stats: result.stats,
      judges,
    }
  }

  async select(options: SelectOptions, signal?: AbortSignal): Promise<SelectResult> {
    if (!options.candidates.length) throw new Error('llm-verifier: candidates must not be empty')
    if (options.candidates.some(candidate => candidate.trim() === '')) throw new Error('llm-verifier: candidates must not contain blank entries')
    if (options.candidates.length > 1 && options.candidates.every(candidate => candidate === options.candidates[0])) return this.identicalCandidates(options.candidates)
    if (options.candidates.length > 1 && new Set(options.candidates).size !== options.candidates.length) return this.selectUnique(options, signal)
    if (options.candidates.length === 1) {
      const judges: JudgeScore[] = this.clients.map(client => ({
        provider: client.provider,
        model: client.model,
        label: judgeLabel(client),
        ok: true,
        calls: 0,
        scores: [1],
        ranking: [0],
      }))
      return { index: 0, best: options.candidates[0]!, scores: [1], ranking: [0], pivots: [0], comparisons: 0, calls: 0, stats: blankStats(), judges }
    }
    if (options.candidates.length === 2) {
      // ringCycle(2) would judge the single unordered pair in both directions; play it
      // once, in the orientation orientPair() picks so the slot is not always candidate 0.
      const single = orientPair(0, 1)
      const { rewards, judgeRewards, judgeOk, judgeErrors, judgeCalls, stats } = await this.scorePairs(options, [single], signal)
      const wins = [0, 0]; const counts = [0, 0]
      accumulatePairs([single], rewards, wins, counts)
      const ranked = rankScores(wins, counts); const index = ranked[0]!.index
      const judges: JudgeScore[] = this.clients.map((client, k) => {
        const isOk = judgeOk[k]!
        if (!isOk) {
          return {
            provider: client.provider,
            model: client.model,
            label: judgeLabel(client),
            ok: false,
            calls: judgeCalls[k]!,
            ...(judgeErrors[k] !== undefined ? { error: judgeErrors[k] } : {}),
          }
        }
        const jWins = [0, 0]; const jCounts = [0, 0]
        accumulatePairs([[0, 1]], judgeRewards[k]!, jWins, jCounts)
        const jRanked = rankScores(jWins, jCounts)
        return {
          provider: client.provider,
          model: client.model,
          label: judgeLabel(client),
          ok: true,
          calls: judgeCalls[k]!,
          scores: jWins.map((val, c) => val / (jCounts[c] || 1)),
          ranking: jRanked.map(v => v.index),
        }
      })
      return { index, best: options.candidates[index]!, scores: wins.map((value, candidate) => value / (counts[candidate] || 1)), ranking: ranked.map(value => value.index), pivots: [], comparisons: 1, calls: stats.calls, stats, judges }
    }
    const ring = ringCycle(options.candidates.length, options.seed ?? 0)
    const ringScores = await this.scorePairs(options, ring, signal)
    const firstWins = new Array<number>(options.candidates.length).fill(0)
    const firstCounts = new Array<number>(options.candidates.length).fill(0)
    accumulatePairs(ring, ringScores.rewards, firstWins, firstCounts)
    const pivots = topPivots(firstWins, firstCounts, options.pivots ?? 2)
    // pivotRoundPairs regenerates every ring edge that touches a pivot (reversed for
    // pivot→neighbour edges). Dropping those duplicates keeps each unordered pair to a
    // single match so wins/counts are not double-weighted and no pair is judged twice.
    const ringPairs = new Set(ring.map(pair => unorderedPair(pair[0], pair[1])))
    const rounds = orientRoundPairs(pivotRoundPairs(options.candidates.length, pivots).filter(pair => !ringPairs.has(unorderedPair(pair[0], pair[1]))))
    const roundScores = await this.scorePairs(options, rounds, signal)
    const allRewards = new Map([...ringScores.rewards, ...roundScores.rewards])
    const wins = new Array<number>(options.candidates.length).fill(0)
    const counts = new Array<number>(options.candidates.length).fill(0)
    accumulatePairs(ring, allRewards, wins, counts)
    accumulatePairs(rounds, allRewards, wins, counts)
    const ranked = rankScores(wins, counts)
    const index = ranked[0]!.index
    const stats = blankStats()
    for (const source of [ringScores.stats, roundScores.stats]) {
      addUsage(stats, source)
      stats.cacheHits += source.cacheHits
      stats.cacheMisses += source.cacheMisses
      stats.topLogprobScores += source.topLogprobScores
      stats.explicitTagScores += source.explicitTagScores
      if (source.usageIncomplete) stats.usageIncomplete = true
      if (source.channelFallbacks) stats.channelFallbacks = (stats.channelFallbacks ?? 0) + source.channelFallbacks
    }

    const judges: JudgeScore[] = this.clients.map((client, k) => {
      const isOk = ringScores.judgeOk[k]! && roundScores.judgeOk[k]!
      const totalCalls = ringScores.judgeCalls[k]! + roundScores.judgeCalls[k]!
      const firstError = ringScores.judgeErrors[k] ?? roundScores.judgeErrors[k]
      if (!isOk) {
        return {
          provider: client.provider,
          model: client.model,
          label: judgeLabel(client),
          ok: false,
          calls: totalCalls,
          ...(firstError !== undefined ? { error: firstError } : {}),
        }
      }
      const jAllRewards = new Map([...ringScores.judgeRewards[k]!, ...roundScores.judgeRewards[k]!])
      const jWins = new Array<number>(options.candidates.length).fill(0)
      const jCounts = new Array<number>(options.candidates.length).fill(0)
      accumulatePairs(ring, jAllRewards, jWins, jCounts)
      accumulatePairs(rounds, jAllRewards, jWins, jCounts)
      const jRanked = rankScores(jWins, jCounts)
      return {
        provider: client.provider,
        model: client.model,
        label: judgeLabel(client),
        ok: true,
        calls: totalCalls,
        scores: Array.from({ length: options.candidates.length }, (_, c) => jWins[c]! / (jCounts[c] || 1)),
        ranking: jRanked.map(v => v.index),
      }
    })

    return { index, best: options.candidates[index]!, scores: Array.from({ length: options.candidates.length }, (_, candidate) => wins[candidate]! / (counts[candidate] || 1)), ranking: ranked.map(value => value.index), pivots, comparisons: ring.length + rounds.length, calls: stats.calls, stats: this.finishStats(stats), judges }
  }
}

/**
 * Normalize a caller-supplied `criteria` argument into the engine's canonical shape.
 *
 * Mirrors upstream's `normalize_criteria` so a caller does not have to fill in every field: a
 * plain string is both the name and the instruction, and a missing `id` is slugged from the
 * name (the score cache keys on the rendered prompt, so a slug is cosmetic). Ids are
 * de-duplicated because `compare` groups per-criterion results by id — a collision would
 * silently merge two criteria into one line of the verdict.
 * @param input - undefined (the default rubric), or a non-empty array of strings/objects.
 * @returns The criteria the engine will score with.
 */
export function normalizeCriteria(input: unknown): Criterion[] {
  if (input === undefined) return DEFAULT_CRITERIA
  if (!Array.isArray(input) || !input.length) throw new Error('llm-verifier: criteria must be a non-empty array')
  const seen = new Set<string>()
  return input.map((value, index) => {
    if (typeof value === 'string') {
      const text = value.trim()
      if (!text) throw new Error('llm-verifier: criteria[' + index + '] must not be blank')
      return { id: dedupeCriterionId(slugCriterionId(text), seen), name: text, description: text }
    }
    if (typeof value !== 'object' || value === null) throw new Error('llm-verifier: criteria[' + index + '] must be a string or an object')
    const row = value as Record<string, unknown>
    const field = (key: string) => (typeof row[key] === 'string' ? (row[key] as string).trim() : '')
    const description = field('description')
    if (!description) throw new Error('llm-verifier: criteria[' + index + '].description must be a non-empty string')
    const name = field('name') || field('id') || slugCriterionId(description)
    const id = field('id') || slugCriterionId(name)
    return { id: dedupeCriterionId(id, seen), name, description }
  })
}
